use "./sim.ts" { createBall, step, draw }

page Sim "/" {
  ref box
  ref balls
  ref raf
  state count = 5
  state frames = 0
  state paused = false
  ref isPaused

  fn reset() {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push(createBall(400, 300))
    }
    count = balls.length
    frames = 0
  }

  fn add() {
    balls.push(createBall(400, 300))
    count = balls.length
  }

  fn toggle() {
    paused = !paused
    isPaused = paused
  }

  fn loop() {
    if !isPaused {
      step(balls, 400, 300)
      frames = frames + 1
    }
    draw(box, balls)
    raf = requestAnimationFrame(loop)
  }

  mount {
    isPaused = false
    reset()
    raf = requestAnimationFrame(loop)
    cleanup { cancelAnimationFrame(raf) }
