export function createBall(w: number, h: number) {
  const r = 10;
  return {
    x: r + Math.random() * (w - 2 * r),
    y: r + Math.random() * (h - 2 * r),
    vx: (Math.random() - 0.5) * 6,
    vy: (Math.random() - 0.5) * 6,
    r,
  };
}

export function step(balls: any[], w: number, h: number) {
  for (const b of balls) {
    b.vy += 0.2;
    b.x += b.vx;
    b.y += b.vy;
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x > w - b.r) { b.x = w - b.r; b.vx = -Math.abs(b.vx); }
    if (b.y < b.r) { b.y = b.r; b.vy = Math.abs(b.vy); }
    if (b.y > h - b.r) { b.y = h - b.r; b.vy = -Math.abs(b.vy); }
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const d = Math.hypot(dx, dy);
      const min = a.r + b.r;
      if (d < min) {
        const nx = d === 0 ? 1 : dx / d;
        const ny = d === 0 ? 0 : dy / d;
        const overlap = min - d;
        a.x -= nx * overlap / 2;
        a.y -= ny * overlap / 2;
        b.x += nx * overlap / 2;
        b.y += ny * overlap / 2;
        for (const p of [a, b]) {
          if (p.x < p.r) p.x = p.r;
          if (p.x > w - p.r) p.x = w - p.r;
          if (p.y < p.r) p.y = p.r;
          if (p.y > h - p.r) p.y = h - p.r;
        }
        const t = a.vx; a.vx = b.vx; b.vx = t;
        const u = a.vy; a.vy = b.vy; b.vy = u;
      }
    }
  }
}

export function draw(canvas: HTMLCanvasElement, balls: any[]) {
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = "#e11d48";
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fill();
  }
}

