page Sim "/" {
  ref box
  ref balls
  ref raf
  ref isPaused
  state count = 5
  state frames = 0
  state paused = false

  fn makeBall() {
    let r = 10
    return {
      x: r + Math.random() * (400 - 2 * r),
      y: r + Math.random() * (300 - 2 * r),
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.5) * 6,
      r: r
    }
  }

  fn reset() {
    let list = []
    for (let i = 0; i < 5; i++) {
      list.push(makeBall())
    }
    balls = list
    count = list.length
    frames = 0
  }

  fn add() {
    balls.push(makeBall())
    count = balls.length
  }

  fn toggle() {
    paused = !paused
    isPaused = paused
  }

  fn walls(b) {
    if b.x < b.r {
      b.x = b.r
      b.vx = Math.abs(b.vx)
    }
    if b.x > 400 - b.r {
      b.x = 400 - b.r
      b.vx = -Math.abs(b.vx)
    }
    if b.y < b.r {
      b.y = b.r
      b.vy = Math.abs(b.vy)
    }
    if b.y > 300 - b.r {
      b.y = 300 - b.r
      b.vy = -Math.abs(b.vy)
    }
  }

  fn step() {
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      walls(b)
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let b = balls[j]
        let dx = b.x - a.x
        let dy = b.y - a.y
        let d = Math.sqrt(dx * dx + dy * dy)
        let min = a.r + b.r
        if d < min {
          let nx = 1
          let ny = 0
          if d > 0 {
            nx = dx / d
            ny = dy / d
          }
          let overlap = min - d
          a.x -= nx * overlap / 2
          a.y -= ny * overlap / 2
          b.x += nx * overlap / 2
          b.y += ny * overlap / 2
          walls(a)
          walls(b)
          let tx = a.vx
          a.vx = b.vx
          b.vx = tx
          let ty = a.vy
          a.vy = b.vy
          b.vy = ty
        }
      }
    }
  }

  fn draw() {
    let ctx = box.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#e11d48"
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn loop() {
    if !isPaused {
      step()
      frames = frames + 1
    }
    draw()
    raf = requestAnimationFrame(loop)
  }

  mount {
    isPaused = false
    reset()
    raf = requestAnimationFrame(loop)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    title "Simulación de pelotas"
    canvas ref=box id="sim" width=400 height=300 style="border:1px solid #888"
    row gap=2 {
      button "Agregar" primary -> add()
      button `${paused ? "Reanudar" : "Pausar"}` -> toggle()
      button "Reiniciar" danger -> reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

page Sim "/" {
  state count = 5
  state frames = 0
  state paused = false
  ref cv
  ref balls
  ref raf
  ref pausedRef
  ref framesRef

  fn rnd(a, b) {
    return a + Math.random() * (b - a)
  }

  fn makeBall() {
    return { x: rnd(10, 390), y: rnd(10, 290), vx: rnd(-3, 3), vy: rnd(-3, 3), r: 10 }
  }

  fn reset() {
    let arr = []
    for (let i = 0; i < 5; i++) {
      arr.push(makeBall())
    }
    balls = arr
    count = 5
    frames = 0
    framesRef = 0
  }

  fn add() {
    balls.push(makeBall())
    count = balls.length
  }

  fn togglePause() {
    paused = !paused
    pausedRef = paused
  }

  fn step() {
    let W = 400
    let H = 300
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      if b.x < b.r {
        b.x = b.r
        b.vx = Math.abs(b.vx)
      }
      if b.x > W - b.r {
        b.x = W - b.r
        b.vx = -Math.abs(b.vx)
      }
      if b.y < b.r {
        b.y = b.r
        b.vy = Math.abs(b.vy)
      }
      if b.y > H - b.r {
        b.y = H - b.r
        b.vy = -Math.abs(b.vy)
      }
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let c = balls[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let d = Math.sqrt(dx * dx + dy * dy)
        if d < a.r + c.r {
          let tx = a.vx
          let ty = a.vy
          a.vx = c.vx
          a.vy = c.vy
          c.vx = tx
          c.vy = ty
          if d > 0 {
            let o = (a.r + c.r - d) / 2
            let nx = dx / d
            let ny = dy / d
            a.x -= nx * o
            a.y -= ny * o
            c.x += nx * o
            c.y += ny * o
            a.x = Math.min(Math.max(a.x, a.r), W - a.r)
            a.y = Math.min(Math.max(a.y, a.r), H - a.r)
            c.x = Math.min(Math.max(c.x, c.r), W - c.r)
            c.y = Math.min(Math.max(c.y, c.r), H - c.r)
          }
        }
      }
    }
  }

  fn draw() {
    let ctx = cv.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#e11d48"
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn loop() {
    if !pausedRef {
      step()
      draw()
      framesRef = framesRef + 1
      frames = framesRef
    }
    raf = requestAnimationFrame(loop)
  }

  mount {
    pausedRef = false
    framesRef = 0
    reset()
    draw()
    raf = requestAnimationFrame(loop)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    canvas ref=cv id="sim" width=400 height=300 style="border:1px solid #888"
    row gap=2 {
      button "Agregar" -> add()
      button (paused ? "Reanudar" : "Pausar") -> togglePause()
      button "Reiniciar" -> reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}
